head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.param1 = "";
scwin.param2 = "";

// 신청자 정보 조회 하는 팝업

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function() {
    try {
        const arrPar = new Array();
        const parentWin = $c.frame.path("../");
        const fn_GetPar = parentWin.fn_GetParam;
        if (fn_GetPar !== undefined) {
            fn_GetPar(arrPar);
            scwin.param1 = ((arrPar.length >= 1) && (arrPar[0] !== undefined) ? arrPar[0] : "");
            scwin.param2 = ((arrPar.length >= 1) && (arrPar[1] !== undefined) ? arrPar[1] : "");
            await scwin.ins_search();
        }
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDINS93600.onpageload" });
    }
};

/**
 * @method
 * @name onpageunload
 * @description 화면 언로드 시 정리 처리
 * @returns {void}
 * @hidden N
 */
scwin.onpageunload = function() {
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name dts_List_OnLoadError
 * @description dts_List 로드 오류 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dts_List_OnLoadError = async function() {
    try {
        await $c.win.alert(dts_List);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDINS93600.dts_List_OnLoadError" });
    }
};

/**
 * @method
 * @name btn_close_onclick
 * @description 「닫기」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_close_onclick = async function() {
    try {
        await $c.win.closePopup();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDINS93600.btn_close_onclick" });
    }
};

/**
 * @method
 * @name dts_List_OnLoadCompleted
 * @description dts_List 로드 완료 후처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} rowcount 조회 건수
 * @returns {void}
 * @hidden N
 */
scwin.dts_List_OnLoadCompleted = function(rowcount) {
    // alert('dts_List.OnLoadCompleted('+rowcount+')');

};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name ins_search
 * @description 신청자 정보 조회 하는
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.ins_search = async function() {
    let queryId = "";
    // 신청자 정보 조회 하는
    // param1 => STD_CD_APPL_ID , ISUR_APPL_ID
    queryId = "lds.ins.common.select.listApctInfoInquiry";
    // alert(queryId);
    const sbmOptions = {
        id : "sbm_dts_List",
        action : "/listingCommon.do",
        ref : "",
        target : "dts_List=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

};
